import net.minecraft.server.level.ServerLevel;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.level.ClipContext;
import net.minecraft.world.phys.AABB;
import net.minecraft.world.phys.BlockHitResult;
import net.minecraft.world.phys.HitResult;
import net.minecraft.world.phys.Vec3;

/** 距离用脚底到碰撞箱最近点。遮挡从眼睛打到同一点，只挡方块，不挡实体和流体。 */
public final class BlockOcclusion {
    private BlockOcclusion() {
    }

    public static Vec3 closestPoint(Vec3 origin, AABB bounds) {
        if (origin == null || bounds == null) {
            throw new IllegalArgumentException("bounds");
        }
        double clampedX = clamp(origin.x, bounds.minX, bounds.maxX);
        double clampedY = clamp(origin.y, bounds.minY, bounds.maxY);
        double clampedZ = clamp(origin.z, bounds.minZ, bounds.maxZ);
        return new Vec3(clampedX, clampedY, clampedZ);
    }

    public static boolean withinRadius(double distanceSquared, double radius) {
        if (Double.isNaN(distanceSquared) || distanceSquared < 0.0D || Double.isInfinite(distanceSquared)) {
            return false;
        }
        if (!(radius > 0.0D) || Double.isNaN(radius) || Double.isInfinite(radius)) {
            return false;
        }
        return distanceSquared <= radius * radius;
    }

    /** 偏移取眼睛到最近点，与视线点积必须为正。零向量不算在前方。 */
    public static boolean inFront(Vec3 eye, Vec3 closest, Vec3 look) {
        if (eye == null || closest == null || look == null) {
            return false;
        }
        double offsetX = closest.x - eye.x;
        double offsetY = closest.y - eye.y;
        double offsetZ = closest.z - eye.z;
        double dot = offsetX * look.x + offsetY * look.y + offsetZ * look.z;
        return dot > 0.0D;
    }

    public static boolean clearOfBlocks(ServerLevel level, ServerPlayer caster, Vec3 closest) {
        if (level == null || caster == null || closest == null) {
            return false;
        }
        if (!Double.isFinite(closest.x) || !Double.isFinite(closest.y) || !Double.isFinite(closest.z)) {
            return false;
        }
        Vec3 eye = caster.getEyePosition();
        if (eye.distanceToSqr(closest) <= 1.0E-8D) {
            return true;
        }
        BlockHitResult hit = level.clip(new ClipContext(
                eye, closest, ClipContext.Block.COLLIDER, ClipContext.Fluid.NONE, caster));
        return hit.getType() == HitResult.Type.MISS;
    }

    private static double clamp(double sample, double lower, double upper) {
        if (sample < lower) {
            return lower;
        }
        if (sample > upper) {
            return upper;
        }
        return sample;
    }
}
"}, {"path": "D:/alianximod/src/main/java/com/bslx/XueXiMod/shu/technique/release/prison/PrisonShell.java", "sha256": "b3585c9a180ac2780f496974e8170a216259b10579318721bccaf338fa0c2cc4", "content": "package com.bslx.XueXiMod.shu.technique.release.prison;

import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.phys.AABB;

import java.util.UUID;

/** 创建时把目标真实包围盒外扩 0.20 格作为壳。接触只算这层壳，不算盒子内部。 */
public final class PrisonShell {
    public static final double PADDING = 0.20D;

    private PrisonShell() {
    }

    public static AABB expand(AABB body) {
        return expand(body, 1.0D);
    }

    /** 以目标包围盒中心放大原外壳。倍率不是有限正数时保持原外壳。 */
    public static AABB expand(AABB body, double sizeMultiplier) {
        if (body == null) {
            return null;
        }
        AABB outer = body.inflate(PADDING);
        return scaleAbout(body, outer, sizeMultiplier);
    }

    public static AABB innerOf(AABB outer) {
        if (outer == null) {
            return null;
        }
        AABB inner = outer.inflate(-PADDING);
        if (inner.maxX <= inner.minX || inner.maxY <= inner.minY || inner.maxZ <= inner.minZ) {
            return null;
        }
        return inner;
    }

    /** 原内盒按同一倍率从目标中心放大后冻结。不用固定填充从放大后的外壳反推。 */
    public static AABB innerFor(AABB body, double sizeMultiplier) {
        AABB inner = innerOf(expand(body, 1.0D));
        if (body == null || inner == null) {
            return null;
        }
        return scaleAbout(body, inner, sizeMultiplier);
    }

    private static AABB scaleAbout(AABB centerBox, AABB targetBox, double sizeMultiplier) {
        double factor = sizeMultiplier;
        if (!Double.isFinite(factor) || factor <= 0.0D) {
            factor = 1.0D;
        }
        double centerX = (centerBox.minX + centerBox.maxX) * 0.5D;
        double centerY = (centerBox.minY + centerBox.maxY) * 0.5D;
        double centerZ = (centerBox.minZ + centerBox.maxZ) * 0.5D;
        return new AABB(
                centerX + (targetBox.minX - centerX) * factor,
                centerY + (targetBox.minY - centerY) * factor,
                centerZ + (targetBox.minZ - centerZ) * factor,
                centerX + (targetBox.maxX - centerX) * factor,
                centerY + (targetBox.maxY - centerY) * factor,
                centerZ + (targetBox.maxZ - centerZ) * factor);
    }

    public static boolean touches(AABB outer, AABB inner, LivingEntity candidate, UUID prisonerId) {
        if (outer == null || candidate == null || prisonerId == null || prisonerId.equals(candidate.getUUID())) {
            return false;
        }
        AABB body = candidate.getBoundingBox();
        if (body == null || !body.intersects(outer)) {
            return false;
        }
        if (inner == null) {
            return true;
        }
        return body.minX < inner.minX || body.maxX > inner.maxX
                || body.minY < inner.minY || body.maxY > inner.maxY
                || body.minZ < inner.minZ || body.maxZ > inner.maxZ;
    }
}
"}, {"path": "D:/alianximod/docs/水牢设计与实现指导-2026-10-26.md", "sha256": "292a006948ac80d8550d9784253e4ba67daa0eb8735397d022fd977c9ee4a230", "content": "# 水牢设计与实现指导（2026-10-26）

本文只记录水牢。让锋不在这次实现里。禁锢、破裂结算、周期伤害、偏转和客户端壳由另外的写入范围完成；这里只登记术式，并把释放、费用、冷却和接触附魔接到已冻结的条件能力上。

## 玩家可见

术式编号 `water_prison`，显示名「水牢」，法术、水属性、基础伤害 0、基础冷却 400 tick、复杂度 0、等级上限 20。法术装配界面的魔力读 `Technique.manaCost()`。只有带条件释放且写了非负显式费用的术式才改走这份显式费用，所以水牢显示 40。领域、规则和按伤害计价的旧术式仍走原来的公式。伤害数字仍是 0，没有改成正数去冒充攻击。

说明文案只写玩法：对准二十格内一个已经潮湿的生物，把它关进水牢；关不进去就不耗魔力。没有新贴图，法术加水属性继续用现成的水系图标。

## 已确认规则在这一侧怎么落地

1. 目标由牢服务的 `selectTarget(施术者, 20)` 决定：二十格准星、先挡方块、不跳过前面的不湿生物。释放侧不自己再找目标，也不把动作撞到的生物塞进去。
2. 魔力 40、冷却 400 走现有扣款和 `CastCooldown` / `ChainSteps`。没有第二套冷却。显式魔力进按键费用；非分步链的零伤尾段只有条件释放才采用基础冷却再做公共缩减。分步链本来就会把 400 加进该步冷却。
3. 没有目标、超距、被挡住、不湿或已经有牢，选择或准备失败。这一发不提交份额。同一次按键里一次都没有提交成功时，不记冷却、不推进分步游标。已经有一次提交成功时，仍按该次冷却记重放。成功之后提前破裂不退这 40。
4. 同一父释放、同一成员、同一波次、同一次动作接触共用一个意图编号，复制序号不进编号。编号来自 `HostCast` 的令牌，再混入成员、波次和接触编号，不用「主人 + tick」。一分为三只 `attempt` 一次，基费 40 一次，附魔费用也不乘 3。双重的两个成员、动作的每次接触各自一个意图，各算一笔。
5. 零伤接触附魔认 `supportsContact`。没有附加伤害的接触附魔仍在扣费前整次拒绝，不会印到主手。有接触伤害的快照交给牢服务的 `commit`，由牢在创建成功后绑定；释放侧不自己打开接触状态。
6. 水牢伤害保持 0。不登记水系命中效果，避免打出命中体。周期伤害、禁锢和壳不是这条释放的职责。

## 文件接点

条件能力在 `release.conditional`：

- `ConditionalEffect.attempt(施术者, 意图编号, 接触快照)` 返回 `ConditionalResult`。默认 `copiesCoalesce` 和 `supportsContact` 都是关。
- `WaterPrisonEffect` 打开这两个开关，并只调用 `PrisonService.selectTarget`、`prepare`、`commit` 和预约的 `close`。未提交的 `close` 释放占用；已经提交的 `close` 不破牢。服务本身不扣魔力。
- `ReleaseDefinition.conditionalEffect()` 默认空。旧术式不声明就保持原路径。

登记：

- `WaterReleaseDefinition.conditional` 写下显式魔力和条件效果，不带领域、屏障、护体或场地。
- `WaterTechniques` 登记术式和释放定义，不登记 `WaterFormEffect`。

钱和冷却：

- 普通单发成功走 `commitRetained`，把这一笔从父收据可退余额划走，再按冷却记重放。失败仍 `cancel` 退这一笔，并退还还没执行的后续段。旧的 `commit` 只打标记，宿主组、攻击预算和反弹预订继续用它，退款语义不变。
- 同一条含条件释放的按键里，已经真正提交的前置术式也用 `commitRetained`。后面的水牢失败不能退掉它们的费用，也不能撤掉它们的冷却。
- 间隔未到只表示已排进调度器，不是成功。回调里 `attempt` 成功才划走魔力，并只给这次真正建成的条件术式记一次熟练度；同一次意图的多份只记一次。还没有任何真实成功时，不记冷却、不推进游标。
- 含条件释放的普通按键在扣款和排程前用现有 `CastCooldown.acquire` 占住槽位。成功、失败、取消和异常都由这一次请求释放一次。双重和动作继续用会话已经取得的那把锁，这里不再取，也不释放。等待尚未成功的条件段时不返回 `deferred`，水牢熟练度不会在按键接受时先加上。
- 非分步时，有条件成员成功则重放至少覆盖该成员缩放后的基础冷却。条件成员都失败、但已有前置成功时，末段若是条件释放就不把 400 算进重放，父冷却仍按非条件末段规则记一次。分步时，有条件成功用原来的整步冷却；条件都失败则去掉这些条件术式的基础冷却后再缩放一次。游标只在父结果提交时推进一次。
- 双重和动作的 `GroupBudget.commit` 会把已提交金额从本组收据划走，结算只退剩余未提交余额。动作已经打中人之后，整步冷却仍含链上的 400，起算点仍是会话结束时。动作没打中人时仍只有动作自己的冷却。
- 没有双重、动作后面又只有一个条件释放、前面没有别的可释放段时，编成现有的动作会话。每次接触单独扣 40 并 `attempt` 一次，目标仍是准星选择。前面或旁边还有斩击、第二段条件释放时，不把整次按键收进这个会话，条件段仍按普通路径在轮到它时提交。
- `CompiledReleaseStep.memberShare` 和双重序列费用在 `copiesCoalesce` 时不乘复制份数。领域、屏障、护体的旧公式不动。

接触：

- `ContactCast` 和 `Technique.canReceiveEnchantment` 把 `supportsContact` 当成可以承载附魔。纯接触伤害小于等于 0 仍拒绝。

`SkillSegmentRunner.commitNow` 遇到条件释放直接拒绝，避免没有回执却报成功。`runSegment` 遇到条件释放直接返回，避免落到命中体。真正提交只走 `commitConditional`。

## 实现默认

- 复杂度 0、等级上限 20，和现有水系成品的登记方式一致。冷却 400 不是等级上限。
- 选择失败统一告诉玩家「没有可禁锢的潮湿目标」。超距、遮挡和不湿都由 `selectTarget` 返回空，释放侧不再拆原因。已经有牢或其他准备失败，用牢服务返回的原因；空原因则说「水牢没有成立」。
- 链上的索敌、落点和弹道不改水牢的目标。水牢不读那些覆盖。
- 壳外扩、禁锢、耗湿、周期伤害、反弹箭和可见壳不在本文件实现。壳外扩 0.20 格是牢服务的实现默认。
- 条件释放排在领域、屏障、护体之后才判断。水牢本身不带这些字段。
- `PrisonReservation.close()` 按冻结签名调用，不声明受检异常。
- 水牢已经划走之后，若后面的领域、屏障或护体同步失败，先把本按键还没执行的条件回调标成终止，再只退未划走的余额。已经建成的水牢不退，成功冷却和使用记录保留，不返回整笔魔力不足。尚未执行的回调看到终止后不再 `attempt`。单独释放失败则不记冷却。

## 生命周期

目标卸载后施术者离场，或正常停服：活动牢立刻结束，只发一次 `ended`。扣湿还没完成时，把未完成的湿记进该维度的 SavedData `xueximod_prison_wet_due`。票据只有 `prisonId`、目标 UUID、维度、锁定等级和结束原因。不留实体，也不把牢恢复出来。目标再次加载，或准备新牢之前，按当时湿度结算这一次，然后删掉票据。当时湿度已经是 0，就直接完成，不 `grant`。同一个 `prisonId` 不登记两次。

原版末地回到主世界、并且这次传送已被接受的那条分支，结束关联的牢。只有这一次非死亡结算、并且确实在该玩家身上扣过湿，才把结算后的数值、剩余时长和服务器 tick 写入 `xueximod_prison_wet_transfer`。非死亡 `Clone` 在对账前把这份快照写到新玩家并消费掉。普通死亡把效果按原版清掉，不抄这份湿度，也不把牢复活。二级仍是结算后的一半，不把持续时间刷新成 1000 tick。其他级结算成 0 之后，旧湿度不能盖回去。等待不延长剩余时间；快照到期就是 0。

三级剩余时间大于 0 时，牢长是 `max(1, 剩余/2)`。剩余 1 tick 成牢 1 tick。剩余 0 或负数不能创建。一级 20 tick，二级 100 tick，四级等于剩余时间。魔力仍是 40，冷却仍是现有链上的 400 tick。

`randomTeleport` 在可取消的方法头里用 `try/finally` 包住。单次跳过标记只放过紧接着的同一次再入调用。

死亡文案键是 `death.attack.water_prison_pressure`。中文「%1$s被水牢的压力压垮了」，英文「%1$s was crushed by water prison pressure」。不称虚空。伤害仍是 4 点，每 20 tick 一次。标签绕过护甲、效果、抗性和附魔，并打末影龙的头。不绕过无敌，也不绕过冷却。

## 校验

`compileJava --offline --no-daemon` 在水牢 QA 时已成功，退出码 0，21 秒。`PrisonService`、`PrisonReservation`、`PrisonCommitResult` 在那次编译里。那一次和当时的门禁都不是启动证明。用户 23:39 的 `runClient` 在 `WetnessDragonMixin` 生成 `Args$1` 后失败。末影龙 `aiStep` 的 `@ModifyArgs` 改为 `require = 2` 的 `@Redirect` 之后，又编译了一次，退出码 0，27 秒。`WetnessStructureGate` 这次把 `observeBeforeGates` 放进返回值，断言 50，失败 0。`WetnessFlightGate` 先因 void 返回指令失败一次，放行该指令后断言 75，失败 0，并且编译类里没有 `Args$1`。计数和原文在 `docs/水牢代码QA-2026-10-26.md`。这次仍没有由 QA 启动客户端，也没有打包。

先前第一次脚本退出码 1，三处是检查器认错了 `commitRetained`、`settleCarrier`、内联的 20、`removePlayerImmediately`、`disarm` 和 `remap=false`。改检查器后这三处重跑退出码 0。时长、壳、向内反射、`confines`、40/400、复制只付一份、收据划走 40、包的 encode/decode、伤害 JSON 和中英死亡文案，是那次实际跑过或读过源码 JSON 的部分。二级减半、重复 `finish`、末地分支和随机传送清理，核对的是字节码形状。当时潮印重跑的 50/0 没有使用 `observeBeforeGates`，不能当成观察顺序已经判过。

偏转审查、发布修复复查、状态修复复查的结果正文都是 **PASS**。三份都写明没有进游戏。QA 没有把源码审查写成运行时通过。

QA 没有启动客户端，也没有打包，没有把 Mixin 变进正在运行的类。因此还没有验证：卸载票据只结算一次、末地克隆保住结算湿度、普通死亡不继承旧效果、玩家退款到账、领域或护体失败后仍扣 40 并保留 400、延迟条件不再建成、缺月与水牢的费用边界、等待锁、动作整步冷却、双重退款、一分为三只扣 40、接触附魔、准星遮挡、周期伤害的无敌帧和黄心、网络投递和画面。这些都不能当成已经测过。
"}]

